<script setup>
import { onMounted, ref } from 'vue';
import { usePropertyAutomationStore } from '@/stores/propertyAutomation';
import { propertyAutomationApi } from '@/api/propertyAutomationApi';
import PropertyInventoryMap from '@/components/PropertyInventoryMap.vue';

const store = usePropertyAutomationStore();
const activeTab = ref('overview');
const filters = ref({ district: '', category: '' });
const selectedPriceProperty = ref(null);
const newPrice = ref('');
const saving = ref(false);
const notice = ref('');
const money = (value) => value == null ? '—' : new Intl.NumberFormat('en-BD', { style: 'currency', currency: 'BDT', maximumFractionDigits: 0 }).format(value);
async function refresh() { await Promise.all([store.loadOverview(), store.loadAlerts()]); }
async function searchMap() { await store.loadMap(filters.value); }
async function acknowledge(id) { await store.acknowledge(id); notice.value = 'Alert acknowledged.'; }
async function openPrice(item) { selectedPriceProperty.value = item; newPrice.value = item.asking_price ?? ''; }
async function savePrice() { if (!selectedPriceProperty.value || newPrice.value === '') return; saving.value = true; try { await propertyAutomationApi.updatePrice(selectedPriceProperty.value.id, Number(newPrice.value)); notice.value = 'Asking price updated and history recorded.'; selectedPriceProperty.value = null; } catch (e) { notice.value = e.response?.data?.message ?? 'Unable to update price.'; } finally { saving.value = false; } }
onMounted(async () => { try { await refresh(); await searchMap(); } catch (e) { notice.value = e.response?.data?.message ?? 'Some automation data could not be loaded.'; } });
</script>

<template>
  <main class="pims-automation">
    <header class="page-head"><div><span class="eyebrow">PROPERTY INTELLIGENCE</span><h1>Maps & Automation</h1><p>Location visibility, inventory health and operational alerts.</p></div><button class="btn-primary" :disabled="store.loading" @click="refresh">↻ Refresh data</button></header>
    <div v-if="notice" class="notice" role="status">{{ notice }} <button @click="notice = ''">×</button></div>
    <nav class="tabs"><button v-for="tab in [{id:'overview',label:'Overview'},{id:'map',label:'Property map'},{id:'alerts',label:'Automation alerts'},{id:'duplicates',label:'Duplicate review'}]" :key="tab.id" :class="{active:activeTab===tab.id}" @click="activeTab=tab.id; if(tab.id==='duplicates') store.loadDuplicates(); if(tab.id==='map') searchMap()">{{ tab.label }}</button></nav>
    <section v-if="activeTab==='overview'" class="stats-grid">
      <article class="stat-card"><span>Expiring in 7 days</span><strong>{{ store.overview.expiring_soon ?? 0 }}</strong><small>Availability reconfirmation</small></article>
      <article class="stat-card"><span>Expired inventory</span><strong>{{ store.overview.expired ?? 0 }}</strong><small>Needs owner confirmation</small></article>
      <article class="stat-card"><span>Properties without map pin</span><strong>{{ store.overview.unmapped ?? 0 }}</strong><small>Location data incomplete</small></article>
      <article class="stat-card"><span>Price changes today</span><strong>{{ store.overview.price_changes ?? 0 }}</strong><small>Recorded in price history</small></article>
      <article class="stat-card"><span>Pending alerts</span><strong>{{ store.overview.pending_alerts ?? 0 }}</strong><small>Awaiting team action</small></article>
    </section>
    <section v-else-if="activeTab==='map'" class="panel">
      <div class="panel-head"><div><h2>Inventory map</h2><p>Available properties with saved coordinates. Up to 500 pins are returned.</p></div></div>
      <div class="filters"><input v-model="filters.district" placeholder="Filter by district"><input v-model="filters.category" placeholder="Category (e.g. Apartment)"><button class="btn-primary" @click="searchMap">Apply filters</button></div>
      <div class="map-layout"><div class="property-pin-list"><article v-for="point in store.mapPoints" :key="point.id" class="pin-item"><strong>{{ point.property_code }} · {{ point.name }}</strong><span>{{ point.area }}, {{ point.district }}</span><b>{{ money(point.asking_price) }}</b><a :href="`https://www.openstreetmap.org/?mlat=${point.latitude}&mlon=${point.longitude}#map=17/${point.latitude}/${point.longitude}`" target="_blank" rel="noopener">Open map ↗</a></article><p v-if="!store.mapPoints.length" class="empty">No mapped available properties found. Add latitude and longitude to property records.</p></div><PropertyInventoryMap v-if="store.mapPoints.length" :properties="store.mapPoints" /><div v-else class="map-placeholder">Map preview appears after at least one property has coordinates.</div></div>
    </section>
    <section v-else-if="activeTab==='alerts'" class="panel"><div class="panel-head"><div><h2>Automation alerts</h2><p>Expiry reminders and inventory aging follow-ups.</p></div><button class="btn-secondary" @click="store.loadAlerts()">Reload</button></div><div class="table-wrap"><table><thead><tr><th>Alert</th><th>Property</th><th>Due</th><th>Created</th><th></th></tr></thead><tbody><tr v-for="item in store.alerts" :key="item.id"><td><strong>{{ item.title }}</strong><small>{{ item.message }}</small></td><td>{{ item.property_id ?? '—' }}</td><td>{{ item.due_at ? new Date(item.due_at).toLocaleDateString() : '—' }}</td><td>{{ new Date(item.created_at).toLocaleDateString() }}</td><td><button class="btn-small" @click="acknowledge(item.id)">Acknowledge</button></td></tr><tr v-if="!store.alerts.length"><td colspan="5" class="empty">No pending alerts.</td></tr></tbody></table></div></section>
    <section v-else class="panel"><div class="panel-head"><div><h2>Potential duplicate properties</h2><p>Grouped by normalized property name, district, area, category and apartment size. Review manually; no records are merged or deleted.</p></div><button class="btn-secondary" @click="store.loadDuplicates()">Scan again</button></div><div v-for="(group,index) in store.duplicates" :key="index" class="duplicate-group"><div class="group-title">Potential duplicate group {{ index+1 }} <span>{{ group.length }} records</span></div><div class="table-wrap"><table><thead><tr><th>Property ID</th><th>Name</th><th>Category</th><th>Location</th><th>Size</th><th>Asking price</th></tr></thead><tbody><tr v-for="p in group" :key="p.id"><td>{{ p.property_code }}</td><td>{{ p.name }}</td><td>{{ p.category }}</td><td>{{ p.area }}, {{ p.district }}</td><td>{{ p.apartment_size_sqft ?? '—' }}</td><td>{{ money(p.asking_price) }}</td></tr></tbody></table></div></div><p v-if="!store.duplicates.length" class="empty">No potential duplicate groups found in the scanned inventory.</p></section>
    <div v-if="selectedPriceProperty" class="modal-backdrop" @click.self="selectedPriceProperty=null"><section class="price-dialog"><button class="close" @click="selectedPriceProperty=null">×</button><h2>Update asking price</h2><p>{{ selectedPriceProperty.property_code }} · {{ selectedPriceProperty.name }}</p><label>New asking price (BDT)</label><input v-model="newPrice" type="number" min="0"><button class="btn-primary" :disabled="saving" @click="savePrice">{{ saving ? 'Saving…' : 'Save price & history' }}</button></section></div>
    <p class="footnote">Mobile use: this page is responsive and uses the same authenticated API as the web application. A native iOS/Android app is a separate client and can consume these endpoints.</p>
  </main>
</template>

<style scoped>
