dding:20px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:680px}th,td{text-align:left;padding:13px 12px;border-bottom:1px solid #edf0f5;font-size:13px}th{color:#718096;font-size:11px;text-transform:uppercase;letter-spacing:.06em}td small{display:block;color:#718096;margin-top:5px;max-width:460px}.duplicate-group{border:1px solid #e8edf4;border-radius:10px;padding:14px;margin-bottom:14px}.group-title{font-weight:800;margin-bottom:10px}.group-title span{font-size:12px;color:#64748b;margin-left:8px}.empty{text-align:center;padding:30px;color:#718096}.notice{background:#eff6ff;border:1px solid #bfdbfe;color:#1e40af;padding:12px 14px;border-radius:9px;margin-bottom:15px}.notice button{float:right;border:0;background:none;color:inherit}.modal-backdrop{position:fixed;inset:0;background:#0f172a88;display:grid;place-items:center;padding:20px;z-index:1000}.price-dialog{position:relative;background:white;border-radius:14px;padding:26px;width:min(430px,100%);display:flex;flex-direction:column;gap:12px}.price-dialog h2{margin:0}.price-dialog p{color:#64748b;margin:0}.price-dialog label{font-size:13px;font-weight:700}.close{position:absolute;right:14px;top:10px;border:0;background:none;font-size:24px}.footnote{font-size:12px;color:#718096;margin-top:18px}.notice,.panel,.stat-card{break-inside:avoid}@media(max-width:1100px){.stats-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.pims-automation{padding:16px}.page-head,.panel-head{align-items:flex-start;flex-direction:column}.stats-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.map-layout{grid-template-columns:1fr}.property-pin-list{max-height:260px}.map-placeholder{height:360px}.filters{flex-direction:column}.filters>*{width:100%}.stat-card{padding:14px}.stat-card strong{font-size:25px}}@media(max-width:420px){.stats-grid{grid-template-columns:1fr 1fr}.stat-card span{font-size:12px}}
